<script setup lang="ts">
import { ChevronDown, ChevronRight } from './icons';
import RenderNode from './RenderNode';
import { inject, computed, ref, nextTick, onBeforeUnmount } from 'vue'; import type { MenuItem } from '../menu-types'; import { menuKey } from '../menu-types'; import { useFloating } from './floating';
const props = withDefaults(defineProps<{ item: MenuItem; depth?: number; nested?: boolean; onActivate?: () => void }>(), { depth: 0 }); const menu = inject(menuKey)!;
const branch = computed(() => props.item.type !== 'group' && !!props.item.children?.length); const inline = computed(() => menu.mode === 'inline' && !menu.collapsed); const flyout = ref(false); const opened = computed(() => inline.value ? menu.openKeys.includes(props.item.key) : flyout.value); const active = computed(() => { function contains(item: MenuItem): boolean { return item.key === menu.selectedKey || !!item.children?.some(contains); } return contains(props.item); });
const { anchor, panel, position } = useFloating(() => opened.value && !inline.value, () => menu.mode === 'horizontal' && !props.nested ? 'bottom-start' : 'right-start', () => { flyout.value = false; }); const list = ref<HTMLElement | null>(null);
function toggle() { if (props.item.disabled) return; if (inline.value) menu.toggle(props.item.key); else flyout.value = !flyout.value; }
let timer: ReturnType<typeof setTimeout>; function schedule(value: boolean) { clearTimeout(timer); if (!inline.value && !props.item.disabled) timer = setTimeout(() => { flyout.value = value; }, value ? 60 : 160); } onBeforeUnmount(() => clearTimeout(timer));
function activate() { flyout.value = false; props.onActivate?.(); }
function select(event: MouseEvent) { if (props.item.disabled) { event.preventDefault(); return; } menu.select(props.item); props.onActivate?.(); }
async function key(event: KeyboardEvent) { if (props.item.disabled) return; if (branch.value && (event.key === 'ArrowRight' || (menu.mode === 'horizontal' && event.key === 'ArrowDown'))) { event.preventDefault(); event.stopPropagation(); if (!opened.value) toggle(); await nextTick(); list.value?.querySelector<HTMLElement>('[role=menuitem]:not(:disabled)')?.focus(); } }
function closeKey(event: KeyboardEvent) { if (event.key === 'Escape' || event.key === 'ArrowLeft') { event.stopPropagation(); event.preventDefault(); if (inline.value) menu.toggle(props.item.key); else flyout.value = false; anchor.value?.focus(); } else menu.keydown(event); }
</script>
<template><li v-if="item.type === 'divider'" role="separator" class="at-menu__divider" /><li v-else-if="item.type === 'group'" role="presentation" class="at-menu__group"><div class="at-menu__group-label">{{ item.label }}</div><ul role="group" class="at-menu__group-list"><MenuNode v-for="child in item.children" :key="child.key" :item="child" :depth="depth" :nested="nested" :on-activate="onActivate" /></ul></li><li v-else role="none" :class="['at-menu__li', { 'at-menu__submenu': branch, 'at-menu__submenu--open': opened }]" @mouseenter="branch && schedule(true)" @mouseleave="branch && schedule(false)"><component :is="item.href && !branch ? 'a' : 'button'" ref="anchor" :href="item.disabled ? undefined : item.href" :type="item.href ? undefined : 'button'" role="menuitem" tabindex="-1" :aria-disabled="item.disabled" :disabled="item.disabled" :aria-current="menu.selectedKey === item.key ? 'page' : undefined" :aria-haspopup="branch ? true : undefined" :aria-expanded="branch ? opened : undefined" :title="menu.collapsed ? item.label : undefined" :class="['at-menu__item', { 'at-menu__title': branch, 'at-menu__title--active': branch && active, 'at-menu__item--selected': !branch && active, 'at-menu__item--disabled': item.disabled, 'at-menu__item--danger': item.danger }]" :style="inline ? { paddingLeft: `${12 + depth * menu.inlineIndent}px` } : undefined" @click="branch ? toggle() : select($event)" @keydown="key"><span v-if="item.icon || menu.collapsed" class="at-menu__icon"><RenderNode :content="item.icon ?? (typeof item.label === 'string' ? item.label.slice(0, 1) : '')" /></span><span class="at-menu__label"><component :is="() => menu.render(item)" /></span><span v-if="branch" class="at-menu__arrow"><ChevronDown v-if="inline || (menu.mode === 'horizontal' && !nested)" :size="14" /><ChevronRight v-else :size="14" /></span></component><div v-if="branch && inline" class="at-menu__inline-panel" :aria-hidden="!opened" :inert="!opened"><ul ref="list" role="menu" class="at-menu__inline-list"><MenuNode v-for="child in item.children" :key="child.key" :item="child" :depth="depth + 1" :on-activate="onActivate" /></ul></div><Teleport v-if="branch && !inline" to="body"><div v-if="opened" ref="panel" class="at-popup at-menu__flyout" :style="position" @mouseenter="schedule(true)" @mouseleave="schedule(false)"><ul ref="list" role="menu" class="at-menu__flyout-list" @keydown="closeKey"><MenuNode v-for="child in item.children" :key="child.key" :item="child" :depth="depth + 1" nested :on-activate="activate" /></ul></div></Teleport></li></template>
